def calculate_stock_volatility(prices):
    # Volatility: standard deviation of prices (basic example)
    if not prices or len(prices) < 2:
        return 0.0
    mean = sum(prices) / len(prices)
    var = sum((p - mean) ** 2 for p in prices) / len(prices)
    return var ** 0.5

def portfolio_risk_assessment(portfolio):
    total_risk = 0.0
    for stock, data in portfolio.items():
        volatility = calculate_stock_volatility(data['prices'])
        weighted_vol = volatility * data['allocation']
        total_risk += weighted_vol
    return total_risk

