def portfolio_risk_assessment(portfolio):
    '''
    Takes a dict where keys are stock names and values have 'prices' (list of floats) and 'allocation' (float).
    For each stock, call calculate_stock_volatility(prices), multiply by allocation, sum all weighted volatilities.
    Returns: float representing total portfolio risk as weighted sum.
    '''

    # Chain-of-thought breakdown:
    # 1. Initialize total_risk = 0.0.
    # 2. For each stock in portfolio:
    #    a. Get prices list and allocation.
    #    b. Compute volatility = calculate_stock_volatility(prices).
    #    c. Weighted risk = volatility * allocation.
    #    d. Add to total_risk.
    # 3. Return total_risk.

    total_risk = 0.0
    for stock, info in portfolio.items():
        prices = info.get('prices', [])
        allocation = info.get('allocation', 0.0)
        # Defensive: if allocation or prices is missing, skip
        if not prices or allocation <= 0.0:
            continue
        volatility = calculate_stock_volatility(prices)
        weighted_volatility = volatility * allocation
        total_risk += weighted_volatility

    return total_risk


